const data = $json.values_lists[0].values;
const allowColors = data.map(value => value.label).join(', '); // Об'єднуємо всі label в один рядок
return { allowColors };

const originalData = $input.all();

// Видаляємо label_translations
const transformedData = originalData.map(item => {
  return item.json.hierarchies.map(hierarchy => {
    const { label_translations, ...rest } = hierarchy;
    return rest;
  });
});

// Розплющуємо всі ієрархії в один масив
const inputJson = transformedData.flat();

// Створюємо мапу категорій
const categoriesMap = {};
inputJson.forEach(category => {
  categoriesMap[category.code] = category;
});

// Шукаємо всі parent-коди
const parentCodes = new Set(
  inputJson
    .map(category => category.parent_code)
    .filter(code => !!code)
);

// Побудова шляху
function createCategoryPath(categoryCode) {
  let category = categoriesMap[categoryCode];
  let path = [];

  while (category) {
    path.unshift(category.label);
    category = categoriesMap[category.parent_code];
  }

  return path.join(' / ');
}

// Лише leaf-категорії
const leafCategories = inputJson
  .filter(category => !parentCodes.has(category.code))
  .map(category => ({
    code: category.code,
    path: createCategoryPath(category.code)
  }))
  .filter(item => item.path.split(' / ').length > 2);

// Додаємо id починаючи з 1
const result = leafCategories.map((item, index) => ({
  id: index + 1,
  ...item
}));

return { result };

const output = $json.output;

// Перевіряємо, чи є дані
if (!output || Object.keys(output).length === 0) {
  return { data: {} };
}

const data = output;
const allowedListCat = $('Patch Categories').first().json.result || [];

// Знаходимо категорію по id (приводимо до числа)
const found = allowedListCat.find(item => Number(item.id) === Number(data.id));

if (found) {
  data.code = found.code;
  data.path = found.path;
}


return { category: data };

const result = $input.first().json.result;

if (!result || result.length === 0) {
  return [{ categories_name: "" }];
}

let categories = result.map(item => ({
  name: item.name,
  parent_name: item.parent_id !== false ? item.parent_id[1] : "",
  prarents_and_self: item.parents_and_self,
  length: item.parents_and_self.length
})).sort((a, b) => b.length - a.length);

let categories_name = categories[0];

let replace_name = result.find(f => f.parent_id === false)?.name + " / ";

return [{
  categories_name: categories_name.parent_name.replace(replace_name, "") + " / " + categories_name.name
}];

const categoriesFromAdeo = $input.first().json.result;
const ctagoryFromOdoo = $('full categories route').first().json.categories_name?.trim() || "";

// Якщо categories_name пустий або ".", то повертаємо весь список
if (!ctagoryFromOdoo || ctagoryFromOdoo === ".") {
  return {filtered: categoriesFromAdeo};
}

// список стоп-слів
const stopWords = ["and", "or", "vj", "of", "for", "the", "then", "a", "an", "to"];

// функція: отримати перше слово після певного символу
function getFirstWordAfter(str, delimiter) {
  const part = str.split(delimiter).pop()?.trim() || "";
  return part.split(/[\/\s]+/)[0]?.toLowerCase() || "";
}

// 1️⃣ беремо слово після останнього "/"
let searchWord = getFirstWordAfter(ctagoryFromOdoo, "/");

// фільтруємо категорії
let filtered = [];
if (searchWord && !stopWords.includes(searchWord)) {
  const rx = new RegExp(`\\b${searchWord}\\b`, "i");
  filtered = categoriesFromAdeo.filter(cat => rx.test(cat.path.toLowerCase()));
}

// 2️⃣ якщо нічого не знайшли → шукаємо слово після "->" (але тільки після останнього "/")
if (filtered.length === 0 && ctagoryFromOdoo.includes("->")) {
  const afterSlash = ctagoryFromOdoo.split("/").pop() || "";
  const afterArrow = afterSlash.split("->").pop()?.trim() || "";
  const fallbackWord = afterArrow.split(/[\/\s]+/)[0]?.toLowerCase() || "";

  if (fallbackWord && !stopWords.includes(fallbackWord)) {
    const rx2 = new RegExp(`\\b${fallbackWord}\\b`, "i");
    filtered = categoriesFromAdeo.filter(cat => rx2.test(cat.path.toLowerCase()));
  }
}

return {filtered: filtered};

const name = ($input.first().json.result[0].name || "").toLowerCase();

const rules = [
  {
    keywords: ["Bird Food", "Bird Seed", "Suet for Birds", "Bird"],
    category: {
      path: "Garden & Terrace / Pet Shop / Bird / Bird Food",
      code: "205123|2795|R09-003-1501",
      color: "Not available",
    }
  },
  {
    keywords: ["beer dispenser", "beer"],
    category: {
      path: "Home appliances / Small household appliances - preparation of drinks / Beer tap",
      code: "205948|1015|R1001-1001",
      color: "Not available",
    }
  },
  {
    keywords: ["coffee"],
    category: {
      path: "Home appliances / Small household appliances - preparation of drinks / Coffee maker and coffee machine / Espresso coffee machine",
      code: "206057|1006|R1001-1001-1001",
      color: "Not available",
    }
  },
  {
    keywords: ["glasses", "glass", "carafe"],
    category: {
      path: "Kitchen / Kitchen accessories and utensil / Mug and glass",
      code: "205785|2195|R05-007",
      color: "Not available",
    }
  },
  {
    keywords: ["Shaker", "Cocktail Mix Set", "Wine Pourer"],
    category: {
      path: "Kitchen / Kitchen accessories and utensil / Kitchen utensils / Kitchen utensils",
      code: "205016|2393|R05-007-2016",
      color: "Not available",
    }
  },
  {
    keywords: ["Brew Kettle", "Mash Kettle", "Copper pot", "cauldron", "pot"],
    category: {
      path: "Kitchen / Kitchen accessories and utensil / Cooking pot",
      code: "205731|2079|R05-007",
      color: "Not available",
    }
  },
  {
    keywords: ["frying pan", "frypan"],
    category: {
      path: "Kitchen / Kitchen accessories and utensil / Frying pan",
      code: "205737|2078|R05-007",
      color: "Not available",
    }
  },
  {
    keywords: ["Waterproof Tarp", "Waterproof tarpaulin"],
    category: {
      path: "Materials / Waterproofing and protection / Provisional protection / Tarpaulin and protection",
      code: "200034|BACHE_ET_PROTECTION|PROTECTION_PROVISOIRE|R01-012-008",
      color: "Not available",
    }
  },
  {
    keywords: ["hose"],
    category: {
      path: "Plumbing / Water supply circuit / Water supply flexible pipe",
      code: "201123|FLEXIBLE_D_ALIMENTATION|CIRCUIT_D_ALIMENTATION_EN_EAU|R14-001",
      color: "Not available",
    }
  }
];

for (const rule of rules) {
  const match = rule.keywords.some(word => name.includes(word.toLowerCase()));
  if (match) {
    return [
      { category: rule.category }
    ];
  }
}

return [
  { category: {} }
];
